// Offline list of the 10,000 most common passwords, stored as SHA-256 digests.
// Source: SecLists `Passwords/Common-Credentials/10k-most-common.txt` (MIT).
// Keeping only digests means the list never ships plaintext passwords and the
// comparison stays a hash lookup. Everything is bundled locally; no network.
const PACKED = '';

let cache = null;

function toHex(bytes) {
  let out = '';
  for (const byte of bytes) out += byte.toString(16).padStart(2, '0');
  return out;
}

export function weakPasswordHashes() {
  if (cache) return cache;
  cache = new Set();
  const binary = atob(PACKED);
  for (let offset = 0; offset + 32 <= binary.length; offset += 32) {
    let digest = '';
    for (let i = 0; i < 32; i += 1) {
      digest += binary.charCodeAt(offset + i).toString(16).padStart(2, '0');
    }
    cache.add(digest);
  }
  return cache;
}

export function isWeakPasswordHash(hex) {
  return weakPasswordHashes().has(String(hex || '').toLowerCase());
}
